// Solo se envían seguimientos en horario razonable (hora de Ecuador).
const DESDE = 8, HASTA = 20;
const h = DateTime.now().setZone('America/Guayaquil').hour;
return h >= DESDE && h < HASTA ? [{ json: {} }] : [];

// Decide a quién toca escribir. Estado por conversación en Redis: v4:seg:<tel>
// (lo actualiza version4 cada vez que el paciente escribe y cada vez que Eli responde).
const TZ = 'America/Guayaquil';
const MIN_BIENVENIDA = 180;    // paso 1 si no respondió al saludo en 3 h
const MIN_CONVERSACION = 120;  // paso 1 si dejó de responder en la conversación por 2 h
const HORAS_ULTIMO = 20;       // paso 2 desde 20 h después del último mensaje del paciente
const HASTA = 20;              // última hora de envío del día

const ahora = DateTime.now().setZone(TZ);
const salida = [];
for (const [key, raw] of Object.entries($json)) {
  if (!key.startsWith('v4:seg:')) continue;
  let s;
  try { s = JSON.parse(raw); } catch (e) { continue; }
  if (!s || !s.in || !s.out || s.paso === 'fin' || s.paso === '2' || s.agendado) continue;
  const tIn = DateTime.fromISO(s.in), tOut = DateTime.fromISO(s.out);
  if (tIn > tOut) continue;                       // el paciente habló último: aún no le responden
  const cierre = tIn.plus({ hours: 24 });          // ventana de WhatsApp
  if (ahora >= cierre.minus({ minutes: 30 })) continue;
  const etapa = (s.n || 1) >= 2 ? 'conversacion' : 'bienvenida';
  const minDesdeEli = ahora.diff(tOut, 'minutes').minutes;
  let paso = null;
  if (!s.paso) {
    if (minDesdeEli >= (etapa === 'bienvenida' ? MIN_BIENVENIDA : MIN_CONVERSACION)) paso = '1';
  } else if (s.paso === '1' && minDesdeEli >= 60) {
    const ultimaHoraHoy = ahora.hour >= HASTA - 1 && cierre < ahora.plus({ days: 1 }).set({ hour: 8, minute: 0 });
    if (ahora.diff(tIn, 'hours').hours >= HORAS_ULTIMO || ultimaHoraHoy) paso = '2';
  }
  if (paso) salida.push({ json: { tel: key.slice('v4:seg:'.length), etapa, paso, estado: s } });
}
return salida;

// Turnos libres de hoy, mañana y pasado mañana (desde la agenda interna de version4).
const hoy = DateTime.now().setZone('America/Guayaquil');
return [0, 1, 2].map(i => ({ json: { accion: 'turnos', fecha: hoy.plus({ days: i }).toFormat('yyyy-MM-dd') } }));

// Arma cada mensaje con los textos de docs/conversacion.md y 2 turnos reales.
const DRY_RUN = false;   // true = solo decide, no envía
const TZ = 'America/Guayaquil';
const hoy = DateTime.now().setZone(TZ).startOf('day');

const turnos = [];
for (const r of $input.all().map(i => i.json)) {
  if (!r.ok) continue;
  for (const t of [...(r.manana || []), ...(r.tarde || [])]) turnos.push({ fecha: r.fecha, hora: String(t).slice(0, 5) });
}
turnos.sort((a, b) => (a.fecha + a.hora).localeCompare(b.fecha + b.hora));
const cuando = x => {
  const d = DateTime.fromISO(x.fecha, { zone: TZ }).setLocale('es');
  const dif = Math.round(d.diff(hoy, 'days').days);
  return (dif === 0 ? 'hoy' : dif === 1 ? 'mañana' : 'el ' + d.toFormat('cccc d')) + ' a las ' + x.hora;
};

const salida = [];
for (const c of $('Elegir seguimientos').all().map(i => i.json)) {
  const primer = String(c.estado.nombre || '').trim().split(/\s+/)[0];
  const nombre = /^[A-Za-zÁÉÍÓÚÑÜáéíóúñü]{2,20}$/.test(primer) ? ', ' + primer : '';
  let texto;
  if (c.etapa === 'bienvenida' && c.paso === '1') {
    texto = 'Hola' + nombre + ' 😊 ¿Pudo ver mi mensaje? Cuénteme con calma qué necesita y le ayudo a encontrar un turno.';
  } else if (c.etapa === 'bienvenida') {
    texto = 'Imagino que tuvo un día ocupado. No le escribo más para no molestar. Cuando quiera agendar, escríbame aquí y le busco un turno 🦷';
  } else if (c.paso === '1') {
    texto = turnos.length >= 2
      ? 'Hola' + nombre + ', tengo estas opciones libres por si le sirven: ' + cuando(turnos[0]) + ' o ' + cuando(turnos[1]) + '. ¿Cuál le queda mejor?'
      : 'Hola' + nombre + ', cuando quiera le busco un turno. ¿Le queda mejor por la mañana o por la tarde?';
  } else {
    texto = 'Le dejo un dato útil: una limpieza cada 6 meses ayuda a prevenir caries y molestias mayores. Cuando quiera, aquí estoy para agendar 🤍';
  }
  const ahora = new Date();
  const estado = { ...c.estado, paso: c.paso, out: ahora.toISOString() };
  const ttl = Math.max(60, Math.round((new Date(estado.in).getTime() + 86400000 - ahora.getTime()) / 1000));
  const memoria = { type: 'ai', data: { content: texto, tool_calls: [], invalid_tool_calls: [], additional_kwargs: {}, response_metadata: {} } };
  salida.push({ json: { enviar: !DRY_RUN, tel: c.tel, pnid: estado.pnid, etapa: c.etapa, paso: c.paso, texto,
    estadoNuevo: JSON.stringify(estado), ttl, memoria: JSON.stringify(memoria) } });
}
return salida;
